 "content": "from collections import deque


def _components(grid, r0, r1, c0, c1):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = []
    for r in range(r0, r1):
        for c in range(c0, c1):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if r0 <= yy < r1 and c0 <= xx < c1 and (yy, xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            out.append((color, cells))
    return out


def transform(grid):
    h, w = len(grid), len(grid[0])
    # The full-length lines are the grid dividers.
    wall = next((v for v in range(1, 10)
                 if any(all(x == v for x in row) for row in grid)), None)
    if wall is None:
        return [row[:] for row in grid]
    row_walls = [r for r, row in enumerate(grid) if all(x == wall for x in row)]
    col_walls = [c for c in range(w) if all(grid[r][c] == wall for r in range(h))]
    rbounds = [-1] + row_walls + [h]
    cbounds = [-1] + col_walls + [w]
    row_ranges = [(rbounds[i] + 1, rbounds[i+1]) for i in range(len(rbounds)-1)]
    col_ranges = [(cbounds[i] + 1, cbounds[i+1]) for i in range(len(cbounds)-1)]

    # The distinctive non-square connected object supplies the repeated silhouette.
    candidates = []
    for r0, r1 in row_ranges:
        for c0, c1 in col_ranges:
            for color, cells in _components(grid, r0, r1, c0, c1):
                ys = [p[0] for p in cells]
                xs = [p[1] for p in cells]
                box_h, box_w = max(ys)-min(ys)+1, max(xs)-min(xs)+1
                solid_square = (box_h == box_w and len(cells) == box_h * box_w)
                candidates.append((len(cells), not solid_square, color,
                                  {(y-min(ys), x-min(xs)) for y, x in cells}))
    _, _, pattern_color, shape = max(candidates, key=lambda z: (z[0], z[1]))

    # Each horizontal band is painted with the color of its square swatch at left.
    band_colors = []
    for r0, r1 in row_ranges:
        comps = _components(grid, r0, r1, *col_ranges[0])
        swatches = [(len(cells), color) for color, cells in comps]
        band_colors.append(max(swatches)[1] if swatches else pattern_color)

    out = [row[:] for row in grid]
    for (r0, r1), color in zip(row_ranges, band_colors):
        for c0, c1 in col_ranges:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    out[r][c] = 0
            for dy, dx in shape:
                # Center the motif within each cell, preserving its orientation.
                top = r0 + (r1-r0-len({y for y, _ in shape} )) // 2
                left = c0 + (c1-c0-len({x for _, x in shape})) // 2
                rr, cc = top + dy, left + dx
                if r0 <= rr < r1 and c0 <= cc < c1:
                    out[rr][cc] = color
    return out
